package com.steven.assets.service.srpp.us;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.steven.assets.srpp.SrppJcs;
import java.time.*;
import java.util.*;

/** Pure publication/read guard. Verifies frozen source and content identity, never reads or changes live state. */
public final class UsReportEnvelopeValidator {
    private UsReportEnvelopeValidator(){}
    public static final Set<String> ROOT=Set.of("schemaVersion","apiScope","status","calculationRunId","identity","calculatorVersion","capturedAt","publishedAt","displayReportTime","session","inputBundle","sourceVector","inputSnapshotSha256","modules","tradeAuthorization","placesOrders","contentSha256");
    public static JsonNode validate(String raw){try{
        JsonNode out=SrppJcs.parseStrict(raw);keys(out,ROOT);require(out.path("schemaVersion").isIntegralNumber()&&out.path("schemaVersion").asInt()==1&&"US_REPORT_CALCULATIONS".equals(text(out,"apiScope"))&&"FINAL".equals(text(out,"status"))&&UsReportPublisher.VERSION.equals(text(out,"calculatorVersion")));falseValue(out,"tradeAuthorization");falseValue(out,"placesOrders");uuid(text(out,"calculationRunId"));hash(text(out,"contentSha256"));
        ObjectNode unsigned=((ObjectNode)out).deepCopy();unsigned.remove("contentSha256");require(SrppJcs.hash(unsigned).equals(text(out,"contentSha256")));
        JsonNode identity=out.path("identity");keys(identity,Set.of("ownerUserId","consumer","market","sessionDate","reportSlot","policyBundleSha256","swaggerSha256"));require(identity.path("ownerUserId").isIntegralNumber()&&identity.path("ownerUserId").asLong()>0&&identity.path("ownerUserId").asLong()<=9007199254740991L&&Set.of("Codex","Claude").contains(text(identity,"consumer"))&&"US".equals(text(identity,"market"))&&UsReportRequest.SLOT.equals(text(identity,"reportSlot")));LocalDate date=LocalDate.parse(text(identity,"sessionDate"));hash(text(identity,"policyBundleSha256"));hash(text(identity,"swaggerSha256"));
        Instant at=Instant.parse(text(out,"capturedAt")),published=Instant.parse(text(out,"publishedAt"));require(!at.isAfter(published)&&date.equals(at.atZone(UsReportCalendar.NY).toLocalDate()));
        JsonNode session=out.path("session");keys(session,Set.of("timezone","open","close","calendarVersion"));require("America/New_York".equals(text(session,"timezone"))&&UsReportCalendar.VERSION.equals(text(session,"calendarVersion")));Instant open=Instant.parse(text(session,"open")),close=Instant.parse(text(session,"close"));require(open.equals(date.atTime(9,30).atZone(UsReportCalendar.NY).toInstant())&&close.equals(date.atTime(UsReportCalendar.EARLY_CLOSE.contains(date)?LocalTime.of(13,0):LocalTime.of(16,0)).atZone(UsReportCalendar.NY).toInstant())&&!at.isBefore(open)&&at.isBefore(close));LocalTime time=at.atZone(UsReportCalendar.NY).toLocalTime();require(!time.isBefore(LocalTime.of(9,40))&&time.isBefore(LocalTime.of(10,45))&&date.atTime(9,45).atZone(UsReportCalendar.NY).withZoneSameInstant(UsReportCalendar.TPE).toLocalTime().toString().equals(text(out,"displayReportTime")));
        JsonNode input=out.path("inputBundle");keys(input,Set.of("ownerUserId","market","sessionDate","reportSlot","capturedAt","sources","stateBefore"));for(String field:List.of("ownerUserId","market","sessionDate","reportSlot"))require(input.path(field).equals(identity.path(field)));require(text(input,"capturedAt").equals(text(out,"capturedAt")));hash(text(out,"inputSnapshotSha256"));require(SrppJcs.hash(input).equals(text(out,"inputSnapshotSha256")));
        JsonNode sources=input.path("sources"),vector=out.path("sourceVector");Set<String> expected=Set.of("assets","policy","swagger","calendar","universe","market","us-tactical","core-state");keys(sources,expected);keys(vector,expected);
        if(!sources.path("assets").isNull()){Instant generated=Instant.parse(text(sources.path("assets"),"generatedAt"));require(!generated.isAfter(at)&&Duration.between(generated,at).compareTo(Duration.ofSeconds(300))<=0);}else require("NONE".equals(vector.path("assets").path("coverage").asText())&&"UNAVAILABLE".equals(vector.path("assets").path("validation").asText()));
        for(String id:expected){JsonNode receipt=vector.path(id);keys(receipt,Set.of("sourceId","revision","capturedAt","sha256","coverage","validation"));String digest=SrppJcs.hash(sources.path(id));require(id.equals(text(receipt,"sourceId"))&&digest.equals(text(receipt,"sha256"))&&digest.equals(text(receipt,"revision"))&&!Instant.parse(text(receipt,"capturedAt")).isAfter(at)&&Set.of("COMPLETE","PARTIAL","NONE").contains(text(receipt,"coverage"))&&Set.of("VERIFIED","UNAVAILABLE").contains(text(receipt,"validation")));}
        JsonNode policy=sources.path("policy");keys(policy,Set.of("rawModelBytes","rawManifestBytes","bundleHash","modelInputsSha256","policyManifestSha256","watchPolicySha256"));require(text(identity,"policyBundleSha256").equals(text(policy,"bundleHash"))&&SrppJcs.sha256Hex(text(policy,"rawModelBytes")).equals(text(policy,"modelInputsSha256"))&&SrppJcs.sha256Hex(text(policy,"rawManifestBytes")).equals(text(policy,"policyManifestSha256")));JsonNode model=SrppJcs.parseStrict(text(policy,"rawModelBytes")),manifest=SrppJcs.parseStrict(text(policy,"rawManifestBytes"));ObjectNode manifestBody=((ObjectNode)manifest).deepCopy();manifestBody.remove("POLICY_BUNDLE_SHA256");require(SrppJcs.hash(manifestBody).equals(text(identity,"policyBundleSha256"))&&manifest.path("files").path("assumptions/model_inputs.json").asText().equals(text(policy,"modelInputsSha256"))&&manifest.path("POLICY_BUNDLE_SHA256").asText().equals(text(identity,"policyBundleSha256"))&&UsCoreSellCalculator.watchPolicyFingerprint(model.path("execution_policy").path("core_sell_guard_d174")).equals(text(policy,"watchPolicySha256")));keys(sources.path("swagger"),Set.of("sha256"));require(text(sources.path("swagger"),"sha256").equals(text(identity,"swaggerSha256")));
        JsonNode state=sources.path("core-state");keys(state,Set.of("ownerUserId","consumer","market","status","reason","importLedgerSha256","watchPolicySha256","ledger","versionVector"));require(state.equals(input.path("stateBefore")));for(String k:List.of("ownerUserId","consumer","market"))require(state.path(k).equals(identity.path(k)));require(Set.of("VERIFIED","UNAVAILABLE").contains(text(state,"status"))&&state.path("versionVector").isObject());boolean stateAvailable="VERIFIED".equals(text(state,"status"));
        if(stateAvailable){hash(text(state,"importLedgerSha256"));require(text(state,"watchPolicySha256").equals(text(policy,"watchPolicySha256"))&&state.path("reason").isNull());JsonNode ledger=state.path("ledger");keys(ledger,Set.of("decision","consumer","states"));require("D-174".equals(text(ledger,"decision"))&&ledger.path("consumer").equals(identity.path("consumer"))&&ledger.path("states").isObject()&&names(ledger.path("states")).equals(names(state.path("versionVector"))));for(var item:ledger.path("states").properties()){JsonNode value=item.getValue();require(item.getKey().equals(value.path("stock_code").asText())&&"美股".equals(value.path("market").asText())&&text(policy,"watchPolicySha256").equals(value.path("policy_sha256").asText()));require(state.path("versionVector").path(item.getKey()).isIntegralNumber()&&state.path("versionVector").path(item.getKey()).asLong()>0);}}
        else require(state.path("reason").isTextual()&&!state.path("reason").asText().isBlank());
        universe(sources,date);
        JsonNode modules=out.path("modules");require(modules.isArray()&&modules.size()==2);for(int i=0;i<2;i++){JsonNode module=modules.get(i);keys(module,Set.of("moduleId","coverage","data","reasonCodes","inputRefs"));String id=i==0?"CORE_SELL_GUARD":"US_TACTICAL";require(id.equals(text(module,"moduleId"))&&Set.of("COMPLETE","PARTIAL","UNAVAILABLE").contains(text(module,"coverage"))&&module.path("data").isObject()&&module.path("reasonCodes").isArray()&&module.path("inputRefs").isArray());JsonNode data=module.path("data");require(data.path("coverage").equals(module.path("coverage"))&&data.path("reasonCodes").equals(module.path("reasonCodes")));for(JsonNode ref:module.path("inputRefs"))require(ref.isTextual()&&sources.has(ref.asText()));falseValue(data,"places_orders");require(data.path("results").isArray());
            if(i==0){keys(data,Set.of("decision","places_orders","requires_daily_hard_gates","watch_updates","watch_stale_symbols","results","stateBefore","stateAfter","coverage","reasonCodes"));require("D-174".equals(text(data,"decision"))&&data.path("requires_daily_hard_gates").isBoolean()&&data.path("requires_daily_hard_gates").asBoolean());if(stateAvailable)require(data.path("stateBefore").equals(state.path("ledger").path("states")));else require("UNAVAILABLE".equals(text(data,"coverage"))&&data.path("stateBefore").isNull()&&data.path("stateAfter").isNull());}
            else{keys(data,Set.of("decision","places_orders","coverage","reasonCodes","results"));require("D-186".equals(text(data,"decision")));for(JsonNode row:data.path("results"))if("COMPLETE".equals(row.path("coverage").asText()))require(row.path("missingSources").isArray()&&row.path("missingSources").isEmpty());}
            if("COMPLETE".equals(text(module,"coverage"))){require(module.path("reasonCodes").isEmpty()&&"COMPLETE".equals(vector.path("assets").path("coverage").asText())&&"VERIFIED".equals(vector.path("assets").path("validation").asText())&&"COMPLETE".equals(sources.path("universe").path("coverage").asText()));if(i==0)require(stateAvailable);else require("VERIFIED".equals(vector.path("us-tactical").path("validation").asText())&&"COMPLETE".equals(vector.path("us-tactical").path("coverage").asText()));}
        }
        // Canonicalization rejects non-integer JSON numbers and unsafe integers anywhere in source or output.
        require(raw.equals(SrppJcs.canonicalize(out)));return out;
    }catch(RuntimeException invalid){if(invalid instanceof UsReportProblem p)throw p;UsReportProblem error=new UsReportProblem("UPSTREAM_INVALID");error.initCause(invalid);throw error;}}
    public static Set<String> names(JsonNode n){Set<String> out=new HashSet<>();n.fieldNames().forEachRemaining(out::add);return out;}
    private static void universe(JsonNode sources,LocalDate date){
        JsonNode universe=sources.path("universe"),market=sources.path("market");keys(universe,Set.of("holdingSymbols","radarSymbols","watchSymbols","symbols","coverage","reasonCodes"));keys(market,Set.of("radarList","symbols"));
        SortedSet<String> held=symbols(universe.path("holdingSymbols")),radar=symbols(universe.path("radarSymbols")),watched=symbols(universe.path("watchSymbols")),all=symbols(universe.path("symbols"));SortedSet<String> union=new TreeSet<>(held);union.addAll(radar);union.addAll(watched);require(all.equals(union));
        if("COMPLETE".equals(universe.path("coverage").asText()))require(universe.path("reasonCodes").isArray()&&universe.path("reasonCodes").isEmpty()&&!sources.path("assets").isNull()&&!market.path("radarList").isNull());
        if(!sources.path("assets").isNull()){SortedSet<String> actual=new TreeSet<>();for(JsonNode row:sources.path("assets").path("snapshot").path("stocks"))if("美股".equals(row.path("market").asText())&&decimal(row.path("shares")).signum()>0)actual.add(text(row,"stockCode"));require(held.equals(actual));}
        if(!market.path("radarList").isNull()){SortedSet<String> actual=new TreeSet<>();for(JsonNode row:market.path("radarList").path("stocks"))if("美股".equals(row.path("market").asText()))require(actual.add(text(row,"stockCode")));require(radar.equals(actual));}
        require(market.path("symbols").isArray());Set<String> seen=new TreeSet<>();for(JsonNode row:market.path("symbols")){keys(row,Set.of("stockCode","quote","radar","coreDirection","historyTrusted","priceHistory","reasonCodes"));String code=text(row,"stockCode");priceHistory(row,date);require(seen.add(code)&&all.contains(code)&&row.path("historyTrusted").isBoolean()&&row.path("reasonCodes").isArray());if(row.hasNonNull("coreDirection"))require(held.contains(code)&&Set.of("CORE_EXIT","CORE_REDUCE").contains(text(row,"coreDirection")));if(!row.path("quote").isNull())require(code.equals(row.path("quote").path("stockCode").asText())&&"美股".equals(row.path("quote").path("market").asText())&&"USD".equals(row.path("quote").path("currency").asText()));}
        require(seen.equals(all));
    }
    private static SortedSet<String> symbols(JsonNode rows){require(rows.isArray());SortedSet<String> out=new TreeSet<>();String previous="";for(JsonNode row:rows){require(row.isTextual()&&!row.asText().isBlank()&&row.asText().compareTo(previous)>0&&out.add(row.asText()));previous=row.asText();}return out;}
    private static void priceHistory(JsonNode row,LocalDate session){
        JsonNode history=row.path("priceHistory");require(history.isArray());JsonNode daily=row.path("quote").path("marketData").path("chart").path("series").path("daily");if(!row.path("quote").isNull())require(daily.path("dates").isArray()&&daily.path("dates").size()==history.size());String previous="";
        for(int i=0;i<history.size();i++){JsonNode bar=history.get(i);keys(bar,Set.of("symbol","market","tradingDate","open","high","low","close","closeSource"));String day=text(bar,"tradingDate");require(text(row,"stockCode").equals(text(bar,"symbol"))&&"美股".equals(text(bar,"market"))&&LocalDate.parse(day).isBefore(session)&&day.compareTo(previous)>0);previous=day;require(bar.path("closeSource").isNull()||bar.path("closeSource").isTextual());if(row.path("historyTrusted").asBoolean())require(bar.path("closeSource").isTextual()&&!bar.path("closeSource").asText().isBlank());
            for(var field:Map.of("open","opens","high","highs","low","lows","close","closes").entrySet()){JsonNode value=bar.path(field.getKey());require(value.isNull()||value.isTextual()||value.isIntegralNumber());if(!row.path("quote").isNull()){require(daily.path(field.getValue()).isArray()&&daily.path(field.getValue()).size()==history.size());JsonNode chart=daily.path(field.getValue()).get(i);require(value.isNull()?chart.isNull():!chart.isNull()&&decimal(value).compareTo(decimal(chart))==0);}}
            if(!row.path("quote").isNull())require(day.equals(daily.path("dates").get(i).asText()));
        }
    }
    private static java.math.BigDecimal decimal(JsonNode n){require(n.isNumber()||n.isTextual());return new java.math.BigDecimal(n.asText());}
    private static void keys(JsonNode n,Set<String> expected){require(n.isObject()&&names(n).equals(expected));}
    private static String text(JsonNode n,String key){require(n.path(key).isTextual());return n.path(key).asText();}
    private static void falseValue(JsonNode n,String key){require(n.path(key).isBoolean()&&!n.path(key).asBoolean());}
    private static void hash(String s){require(s.matches("[a-f0-9]{64}"));}
    private static void uuid(String s){require(s.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"));UUID.fromString(s);}
    private static void require(boolean v){if(!v)throw new IllegalArgumentException("US_ENVELOPE_INVALID");}
}
